+        let mut pts = one.points().to_vec();
+        if pts.len() < 3 {
+            return Ok(out);
+        }
+        if !one.is_ccw() {
+            pts.reverse();
+        }
+        out.push(pts);
+    }
+    Err(invalid(format!("the pocket needs more than {MAX_RINGS} rings - it is too large for one burnout at this wire")))
